from collections import Counter
def f(g):
    h=len(g); w=len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in g]
    for s in (0,1):
        kf=(lambda i,j:(i-j)) if s==0 else (lambda i,j:(i+j))
        gr={}
        for i in range(h):
            for j in range(w):
                c=g[i][j]
                if c==bg: continue
                gr.setdefault(kf(i,j),[]).append((i,j,c))
        for k,lis in gr.items():
            lis.sort(key=lambda p:p[0])
            cur=[lis[0]]; runs=[]
            step=(1,1) if s==0 else (1,-1)
            for cell in lis[1:]:
                if cell[2]==cur[-1][2] and (cell[0]-cur[-1][0],cell[1]-cur[-1][1])==step:
                    cur.append(cell)
                else:
                    runs.append(cur); cur=[cell]
            runs.append(cur)
            for run in runs:
                if len(run)<2: continue
                c=run[0][2]
                di,dj=step
                ni,nj=run[0][0]-di,run[0][1]-dj
                while 0<=ni<h and 0<=nj<w and g[ni][nj]==bg:
                    out[ni][nj]=c; ni-=di; nj-=dj
                ni,nj=run[-1][0]+di,run[-1][1]+dj
                while 0<=ni<h and 0<=nj<w and g[ni][nj]==bg:
                    out[ni][nj]=c; ni+=di; nj+=dj
    return out
